sys_script.script:
(function executeRule(current, previous) {
    var materialId = current.getValue('material_tool');
    var locationId = current.getValue('mro_location');
    var qtyIssued = parseFloat(current.getValue('quantity_issued') || '0');

    if (!materialId || !locationId || qtyIssued <= 0) { return; }

    var stock = new GlideRecord('x_2056099_indust_0_inv_stock');
    stock.addQuery('material_product', materialId);
    stock.addQuery('location', locationId);
    stock.addQuery('inventory_type', 'mro');
    stock.query();

    if (stock.next()) {
        var available = parseFloat(stock.getValue('available_quantity') || '0');
        if (available < qtyIssued) {
            gs.addErrorMessage('Insufficient MRO stock. Available: ' + available + ', Requested: ' + qtyIssued);
            current.setAbortAction(true);
        }
    } else {
        gs.addErrorMessage('No MRO inventory stock found for this material at the specified location');
        current.setAbortAction(true);
    }
})(current, previous);
